INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug", "outdoor_tv_mounting", "outdoor_tv_sun_exposure", "foundation_status") VALUES ('e719911b-5d78-540c-a6f0-b19610966819', 'e0030000-0000-4000-8000-000000000103', 'published', 'Wóz Mieszkalny 40', 'PL', 40, NULL, 'Mieszkalny wóz całoroczny: wnętrze 40 m² oraz zadaszony taras 27 m². W środku są pełnowymiarowa kuchnia z salonem, łazienka z prysznicem i dwie sypialnie. Elewacja jest z modrzewia syberyjskiego, dach z aluminiowej blachy na rąbek stojący, elementy metalowe malowane proszkowo, a wnętrze obite boazerią ze świerku skandynawskiego. Wóz jest ocieplony i wyposażony we wszystkie media, a instalacja elektryczna i hydrauliczna jest wykonana zgodnie z obowiązującymi normami. Cena jest podana w euro, netto, bez transportu.', 'pod-klucz', 4, 4, NULL, NULL, NULL, NULL, 2, 'mobilny', NULL, 2, 1, 1, NULL, 'Dach z aluminiowej blachy na rąbek stojący', 'Elewacja z modrzewia syberyjskiego, wnętrze ze świerku skandynawskiego, dach z aluminiowej blachy na rąbek stojący, całość ocieplona.', NULL, 'Szczegóły wykończenia i kolorystyki do uzgodnienia z producentem.', 'EUR', NULL, NULL, false, '2026-10-30T14:26:20.916Z'::timestamptz, '2026-10-30T14:26:20.962Z'::timestamptz, NULL, 'dom', NULL, '{"heatSource":"inne","insulation":"Do wyboru: piana PUR, wełna mineralna lub włókno drzewne (ściany 200x60 mm).","ventilation":"inna","wallBuildUp":"Stalowa rama nośna, szkielet z drewna konstrukcyjnego C-24 200x60 mm z izolacją do wyboru.","heatSourceOther":"Brak danych w ofercie producenta.","ventilationOther":"Brak danych w ofercie producenta.","constructionTechnology":"inne","heatTransferCoefficients":"nieznana","constructionTechnologyOther":"Brak danych w ofercie producenta."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{"id":"woz-mieszkalny-room-0","name":"Kuchnia z salonem, łazienka i dwie sypialnie","areaM2":40,"floorLevel":"parter"}]'::jsonb, NULL, NULL, NULL, NULL, 'woz-mieszkalny-40', NULL, NULL, 'temporary') ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('af96fbc3-2b89-481a-83be-b481d23768a8', 'e719911b-5d78-540c-a6f0-b19610966819', 'en', 'Wóz Mieszkalny 40', 'A year-round residential wagon: 40 m² inside plus a 27 m² covered terrace. Inside are a full-size kitchen with a living area, a bathroom with a shower and two bedrooms. The facade is Siberian larch, the roof is aluminium standing-seam sheet metal, metal parts are powder-coated, and the interior is lined with Scandinavian spruce panelling. The wagon is insulated and equipped with all utilities, and the electrical and plumbing installations are made to current standards. The price is given in euro, net, excluding transport.', '2026-10-30T14:26:20.916Z'::timestamptz, '2026-10-30T14:26:20.916Z'::timestamptz, '[{"id":"woz-mieszkalny-room-0","name":"Kitchen with living area, bathroom and two bedrooms"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Siberian larch facade, Scandinavian spruce interior, aluminium standing-seam roof, fully insulated.', 'Roof of aluminium standing-seam sheet metal', 'Finishing and colour details to be agreed with the producer.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('88b8ea33-5735-427d-a961-9e4d03b2a8ee', 'e719911b-5d78-540c-a6f0-b19610966819', 'de', 'Wóz Mieszkalny 40', 'Ein ganzjährig bewohnbarer Wagen: 40 m² Innenfläche plus 27 m² überdachte Terrasse. Im Inneren befinden sich eine vollwertige Küche mit Wohnbereich, ein Bad mit Dusche und zwei Schlafzimmer. Die Fassade besteht aus sibirischer Lärche, das Dach aus Aluminium-Stehfalzblech, Metallteile sind pulverbeschichtet, und der Innenraum ist mit skandinavischer Fichte verkleidet. Der Wagen ist gedämmt und mit allen Anschlüssen ausgestattet, Elektro- und Sanitärinstallation sind nach geltenden Normen ausgeführt. Der Preis ist in Euro angegeben, netto, ohne Transport.', '2026-10-30T14:26:20.916Z'::timestamptz, '2026-10-30T14:26:20.916Z'::timestamptz, '[{"id":"woz-mieszkalny-room-0","name":"Küche mit Wohnbereich, Bad und zwei Schlafzimmer"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Fassade aus sibirischer Lärche, Innenraum aus skandinavischer Fichte, Dach aus Aluminium-Stehfalzblech, vollständig gedämmt.', 'Dach aus Aluminium-Stehfalzblech', 'Einzelheiten zu Ausführung und Farbgebung nach Absprache mit dem Hersteller.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('b51e14c7-8f0e-4cf0-95ed-2c16911dc6bb', 'e719911b-5d78-540c-a6f0-b19610966819', 'nl', 'Wóz Mieszkalny 40', 'Een jaarrond bewoonbare woonwagen: 40 m² binnenruimte plus een overdekt terras van 27 m². Binnen zijn een volwaardige keuken met woonruimte, een badkamer met douche en twee slaapkamers. De gevel is van Siberisch lariks, het dak van aluminium liggende felsplaat, metalen onderdelen zijn poedergecoat en het interieur is bekleed met Scandinavisch vurenhout. De woonwagen is geïsoleerd en uitgerust met alle aansluitingen, en de elektrische en sanitaire installatie is volgens de geldende normen uitgevoerd. De prijs is in euro, netto, exclusief transport.', '2026-10-30T14:26:20.916Z'::timestamptz, '2026-10-30T14:26:20.916Z'::timestamptz, '[{"id":"woz-mieszkalny-room-0","name":"Keuken met woonruimte, badkamer en twee slaapkamers"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Gevel van Siberisch lariks, interieur van Scandinavisch vurenhout, dak van aluminium liggende felsplaat, volledig geïsoleerd.', 'Dak van aluminium liggende felsplaat', 'Afwerking en kleurstelling in overleg met de producent.', NULL) ON CONFLICT DO NOTHING;
